  ('bonito-brazil', '10S', 'Bonito, Brazil', 'Brazil', 'Bonito', 'live', 'verified', 'mountainValley', 'Amazon, Pantanal & Iguaçu', '{"wildlife"}', '{}', '{"essential","comfort","premier"}', null, null, '{"key_facts":null,"safety":{"emergency":"190","advisory_level":"L2","advisory_why":"national crime + kidnapping risk indicator concentrated in cities, favelas, and Level-4 border zones — none describe interior Bonito","book_enabled":true,"bin":"freely bookable (L2)","consent_flow":false,"air_access_verified":true,"air_access":{"primary":"Bonito (BYO) — limited commercial service (~13 km from town)","gateway":"Campo Grande (CGR) + road transfer ~205 km / ~3–3.5 hrs"},"trauma_note":"rural interior; serious-trauma/evac route via Campo Grande (CGR); evacuation-coverage insurance essential for adventure stack","health_flag":"chikungunya outbreak reported in Mato Grosso do Sul — mosquito-bite prevention day and night","activity_flags":["river no-touch + no pre-entry sunscreen","cave/waterfall rappel technical + harness","cool water ~18–22°C neoprene"]},"timing":{"clarity_peak":"dry season ~Apr–Oct (core Jun–Sep)","crowd_price_peak":"December → Carnival","low_visibility_window":"Dec–Feb (rain raises rivers)","shoulder":"Mar–Jun (milder, fewer crowds)","inflection":"supply is physically day-capped; slots close weeks ahead in dry window","fire_date":"clarity-curve start − 1–2 weeks (late Mar–May for winter clarity trips; Oct–Nov ahead of Dec–Carnival)","off_season_fill":"dry low-season tail + wet-but-workable shoulder → flexible/budget/photography travelers","note":"attractions sell out, not just hotels — book the voucher itinerary"},"jewels":[{"name":"Rio da Prata float","si_tag":"expedition","tier":"comfort","commission_path":"DMC/AOR → licensed-agency voucher","source":"https://www.tripadvisor.com/ShowUserReviews-g303368-d1936985-r118728253-Rio_da_Prata-State_of_Mato_Grosso_do_Sul.html","si":"expedition","commission":"DMC/AOR → licensed-agency voucher"},{"name":"Rio Sucuri snorkel","si_tag":"expedition","tier":"essential","commission_path":"licensed-agency voucher via AOR","source":"https://www.aventuradobrasil.com/blog/bonito-brazils-natural-gem-of-crystal-clear-rivers-and-hidden-caves/","hook":"Described as one of the clearest rivers on Earth; emerald underwater gardens threaded with pearl-like oxygen bubbles. Gentler/shorter than Prata, superb clarity","si":"expedition","blurb":"Described as one of the clearest rivers on Earth; emerald underwater gardens threaded with pearl-like oxygen bubbles. Gentler/shorter than Prata, superb clarity","commission":"licensed-agency voucher via AOR"},{"name":"Abismo Anhumas rappel + underground-lake dive/snorkel","si_tag":"expedition","tier":"premier","commission_path":"AOR → operator via licensed agency","source":"https://www.explore-share.com/trip/abismo-anhumas-abseiling-underground-lake-bonito/","hook":"72 m descent into a cavern lake with submerged limestone cones up to ~20 m; snorkel or scuba the lake; ~18°C water","si":"expedition","blurb":"72 m descent into a cavern lake with submerged limestone cones up to ~20 m; snorkel or scuba the lake; ~18°C water","commission":"AOR → operator via licensed agency"},{"name":"Boca da Onça waterfall circuit + 90m rappel","si_tag":"expedition","tier":"comfort","commission_path":"AOR → licensed-agency voucher","source":"https://www.bocadaonca.com.br/","hook":"Mato Grosso do Sul''s tallest waterfall; Brazil''s largest platform rappel; ~4,500 m trail, 8 waterfalls, natural pools","si":"expedition","blurb":"Mato Grosso do Sul''s tallest waterfall; Brazil''s largest platform rappel; ~4,500 m trail, 8 waterfalls, natural pools","commission":"AOR → licensed-agency voucher"},{"name":"Estância Mimosa waterfall trek","si_tag":"expedition","tier":"essential","commission_path":"AOR → voucher + room","source":"https://www.aventuradobrasil.com/blog/bonito-brazils-natural-gem-of-crystal-clear-rivers-and-hidden-caves/","hook":"Guided trail to a chain of waterfalls and swimming pools with strong flora/fauna viewing; also offers on-site lodging","si":"expedition","blurb":"Guided trail to a chain of waterfalls and swimming pools with strong flora/fauna viewing; also offers on-site lodging","commission":"AOR → voucher + room"},{"name":"Gruta do Lago Azul","si_tag":"expedition","tier":"essential","commission_path":"voucher via licensed agency; entry fee pass-through","source":"https://en.wikipedia.org/wiki/Gruta_do_Lago_Azul_Natural_Monument","hook":"Guided-mandatory, no swimming. ~300-step descent; closed-toe shoes mandatory; no water access since 1992; the risk here is the stairs, not the water","si":"expedition","blurb":"Guided-mandatory, no swimming. ~300-step descent; closed-toe shoes mandatory; no water access since 1992; the risk here is the stairs, not the water","commission":"voucher via licensed agency; entry fee pass-through"},{"name":"Buraco das Araras (macaw sinkhole)","si_tag":"wildlife","tier":"essential","commission_path":"AOR → licensed reserve access","source":"https://en.wikipedia.org/wiki/Buraco_das_Araras_Private_Natural_Heritage_Reserve","hook":"Huge sandstone crater near Jardim; South America''s largest sinkhole; sanctuary for red-and-green macaws plus toucans/araçaris. Best at early morning / late afternoon","si":"wildlife","blurb":"Huge sandstone crater near Jardim; South America''s largest sinkhole; sanctuary for red-and-green macaws plus toucans/araçaris. Best at early morning / late afternoon","commission":"AOR → licensed reserve access"},{"name":"Night float","si_tag":"wildlife","tier":"comfort","commission_path":"licensed-agency voucher","source":"https://www.livemoretravelmore.com/things-to-do-in-bonito-brazil/","si":"wildlife","commission":"licensed-agency voucher"},{"name":"Pantanal wildlife extension (gateway)","si_tag":"wildlife","tier":"comfort","commission_path":"AOR combo mandate (Bonito + Pantanal)","source":"https://www.aventuradobrasil.com/blog/bonito-brazils-natural-gem-of-crystal-clear-rivers-and-hidden-caves/","hook":"The high-value pairing: Bonito''s clear water + Pantanal''s unmatched wildlife density. Same regional DMC can carry both","si":"wildlife","blurb":"The high-value pairing: Bonito''s clear water + Pantanal''s unmatched wildlife density. Same regional DMC can carry both","commission":"AOR combo mandate (Bonito + Pantanal)"}],"faq":[{"q":"When is the best time to snorkel Bonito''s crystal rivers?","a":"The dry season — roughly June–September, within the broader May–September dry window — delivers the clearest, most predictable water, because the winter rains that raise rivers and drop visibility have stopped; daily visitor slots are physically capped, so book at least a week ahead in high season (July–September).","source":"lonelyplanet.com, 2026-07-07","si_tag":"expedition"},{"q":"Can you actually see wild macaws near Bonito?","a":"Yes — Buraco das Araras, South America''s largest sinkhole (~500 m circumference, ~100 m deep) near Jardim, is a heavily regulated sanctuary for red-and-green macaws plus toucans and araçaris, best viewed at early morning or late afternoon on a guided visit.","source":"en.wikipedia.org, 2026-07-07","si_tag":"wildlife"},{"q":"Is Bonito a good honeymoon destination?","a":"Yes, as a slow water-and-forest romance add-on rather than a luxury-ceremony market: the top of the market is the 4-star Zagaia Eco Resort — grounds, pools and full recreation — with boutique eco-pousadas filling the couples tier, so set expectations to best-in-region eco, not five-star.","source":"evendo.com, 2026-07-07","si_tag":"romance"},{"q":"Is Bonito safe to visit right now?","a":"Yes — Brazil carries a Level 2 \"Exercise Increased Caution\" advisory, but that headline number is driven by crime and a kidnapping risk indicator concentrated in big cities, favelas, and the Level-4 land-border zones within ~160 km of borders — none of which describe Bonito, a small, tightly managed interior eco-town. `book_enabled = true`, no consent flow.","source":"travel.state.gov, 2026-07-07","si_tag":"safety"},{"q":"Is the Abismo Anhumas cave rappel dangerous?","a":"It is a serious, technical activity run safely under a guided-mandatory system: a 72 m harness rappel on electric devices into a cavern lake (~18°C water, submerged cones to ~20 m), capped at a maximum of 16 people per day with certified monitors — never a free-climb and never sold unguided.","source":"explore-share.com, 2026-07-07","si_tag":"safety"},{"q":"What''s the real risk to plan for in Bonito?","a":"Sell-outs, not danger: because every attraction runs on a licensed-agency voucher with hard daily caps, marquee tours like Rio da Prata and Rio Sucuri can sell out weeks ahead of time, so the booking *is* the reservation — reserve the voucher itinerary, not just the room.","source":"en.wikivoyage.org, 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Bonito, Brazil: Crystal-River Snorkeling, Caves & the Pantanal Gateway — TravelWell","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","search_language":"pt-BR","local_keywords":["Bonito MS o que fazer","Rio da Prata flutuação","Gruta do Lago Azul","melhor época para ir a Bonito","Abismo Anhumas rapel","Boca da Onça cachoeira","Bonito e Pantanal roteiro","Buraco das Araras Jardim"],"hreflang":["en","pt-BR"],"primary_keyword":"Bonito"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"wildlife","status":"live"}],"ultra":[{"name":"Zagaia Eco Resort","positioning":"4-star Bonito ceiling","earning":"room commission","mor":"DMC/AOR","tier":"Premium (regional ceiling)"},{"name":"Santa Esmeralda","positioning":"upper-boutique eco-pousada","earning":"room commission / bedbank","mor":"AOR/bedbank","tier":"Premium-lite"},{"name":"Boutique eco-pousadas (curated)","positioning":"design-forward small pousadas — premier eco ceiling, not 5-star","earning":"room commission","mor":"AOR/bedbank","tier":"Mid → Premium-lite"}],"source_verified":null,"hero":{"query":"Bonito, Brazil, Brazil"},"geo":{"lat":-21.1261,"lng":-56.4514}}'::jsonb, 13),
  ('buenos-aires-argentina', '10S', 'Buenos Aires, Argentina', 'Argentina', 'Leather and silk, beef and fire **TravelWell', 'live', 'verified', 'paris', 'Buenos Aires & The Pampas', '{"romance","culture","culinary"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["US State Dept Level 1 - Exercise Normal Precautions (advisory dated 2026-05-20); Rosario is a city-level L2 exception, not on a BA itinerary.","Best experience = spring/fall shoulder (Oct-Nov, Mar-Apr); November brings jacaranda bloom + the Argentine Open Polo.","Signature BA experiences: milonga tango, puerta-cerrada (closed-door) asado, Malbec tasting, Recoleta Cemetery (Evita), Teatro Colon.","Day-trip belt: Tigre Delta (~1 hr), San Antonio de Areco estancia (~1.5 hr), Colonia/Uruguay ferry across the Rio de la Plata.","Petty crime is theft-by-distraction, not force (motochorros, ~90% at traffic lights); La Boca daytime-and-Caminito only; tap water potable."],"safety":{"emergency":"911","police":"101","ambulance":"107","fire":"100","us_embassy_ba":"+54 11 5777-4354","advisory_level":"L1","book_enabled":true,"bin":"freely bookable (L1)","consent_flow":false,"air_access_verified":{"international":"EZE (Ezeiza / Ministro Pistarini)","domestic":"AEP (Aeroparque Jorge Newbery)"},"water":"potable","trauma_path":"BA private hospitals excellent; stabilize locally then US medevac for catastrophic cases"},"timing":{"peak_experience":"Oct-Nov and Mar-Apr (shoulder — best weather/crowds)","peak_volume":"Dec-Feb (austral summer — hot/humid, least comfortable)","inflection_curve_start":"loads ahead of each shoulder window + Nov events","fire_date":"curve-start minus 1-2 weeks (~early Sep for Oct-Nov; ~January for Mar-Apr); November premium = 3-6 months lead","events":[{"name":"Argentine Open Polo Championship","month":"November","venue":"Campo Argentino de Polo, Palermo"},{"name":"Tango BA Festival y Mundial","month":"August (austral winter — NOT November)"}],"low_season":"Jun-Aug (winter; occupancy low ~Apr-Jun — value window)"},"jewels":[{"name":"Private milonga tango night","si_tag":"romance","tier":"comfort","commission_path":"activities affiliate / DMC private experience","source":"https://www.getyourguide.com/buenos-aires-l1/","hook":"The real social tango — a couple''s night at an authentic milonga beats any tourist stage show for a honeymoon","si":"romance","blurb":"The real social tango — a couple''s night at an authentic milonga beats any tourist stage show for a honeymoon","commission":"activities affiliate / DMC private experience"},{"name":"Recoleta jacarandas + Recoleta Cemetery (Evita tomb)","si_tag":"RHN / Culture","tier":"essential","commission_path":"DMC/guide (entry non-commissionable)","source":"https://www.buenosairesfreewalks.com/what-to-do/grave-of-evita-peron/","timing":"year-round","timing_type":"ALWAYS-ON","hook":"A November walk through Recoleta''s lilac-blossom boulevards into the most famous cemetery in the Americas","si":"RHN / Culture","blurb":"A November walk through Recoleta''s lilac-blossom boulevards into the most famous cemetery in the Americas","when":"year-round","commission":"DMC/guide (entry non-commissionable)"},{"name":"Closed-door (puerta cerrada) asado — Fogon Asado","si_tag":"culinary","tier":"premier","commission_path":"activities affiliate / DMC","source":"https://www.getyourguide.com/buenos-aires-l1/buenos-aires-8-course-argentine-bbq-at-fogon-asado-t235877/","hook":"The most intimate, most Porteño dinner in the city — see Culinary below; sells beautifully as a honeymoon night","si":"culinary","blurb":"The most intimate, most Porteño dinner in the city — see Culinary below; sells beautifully as a honeymoon night","commission":"activities affiliate / DMC"},{"name":"Casa Saltshaker puerta cerrada + Malbec flight","si_tag":"culinary","tier":"comfort","commission_path":"DMC-brokered / direct","source":"https://theculturetrip.com/south-america/argentina/articles/the-best-closed-door-restaurants-in-buenos-aires","hook":"Intimate shared-table five-course dinners with Malbec-vs-Patagonian-pinot flights — one of the city''s oldest supper clubs","si":"culinary","blurb":"Intimate shared-table five-course dinners with Malbec-vs-Patagonian-pinot flights — one of the city''s oldest supper clubs","commission":"DMC-brokered / direct"},{"name":"Malbec / Argentine-wine tasting","si_tag":"culinary","tier":"comfort","commission_path":"DMC / activities affiliate","source":"https://theculturetrip.com/south-america/argentina/articles/the-best-closed-door-restaurants-in-buenos-aires","hook":"Guided verticals of Mendoza Malbec, Patagonian pinot, and high-altitude Salta torrontés — in-city tasting rooms or a DMC-curated flight","si":"culinary","blurb":"Guided verticals of Mendoza Malbec, Patagonian pinot, and high-altitude Salta torrontés — in-city tasting rooms or a DMC-curated flight","commission":"DMC / activities affiliate"},{"name":"San Telmo Sunday feria (Calle Defensa)","si_tag":"Culinary / Culture","tier":"essential","commission_path":"content-led; guided-tour affiliate","source":"https://en.wikivoyage.org/wiki/Buenos_Aires","hook":"The Sunday street market and antiques fair — empanadas, choripán, street tango, and browsing","si":"Culinary / Culture","blurb":"The Sunday street market and antiques fair — empanadas, choripán, street tango, and browsing","commission":"content-led; guided-tour affiliate"},{"name":"MALBA — Latin American art museum","si_tag":"culture","tier":"essential","commission_path":"admission non-commissionable; DMC guided visit","source":"https://en.wikivoyage.org/wiki/Buenos_Aires/Palermo_%26_Recoleta","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","when":"year-round","commission":"admission non-commissionable; DMC guided visit"},{"name":"Teatro Colon guided tour / opera night","si_tag":"Culture / RHN","tier":"essential","commission_path":"box-office non-commissionable; DMC package","source":"https://turismo.buenosaires.gob.ar/en","si":"Culture / RHN","commission":"box-office non-commissionable; DMC package"},{"name":"Palermo Soho boutiques","si_tag":"culture","tier":"comfort","commission_path":"content-led; concierge personal-shopper","source":"https://en.wikivoyage.org/wiki/Buenos_Aires/Palermo_%26_Recoleta","hook":"High-end Argentine fashion and leather boutiques on cobblestone streets — the \"silk\" half of BA''s soul","si":"culture","blurb":"High-end Argentine fashion and leather boutiques on cobblestone streets — the \"silk\" half of BA''s soul","commission":"content-led; concierge personal-shopper"},{"name":"La Boca / Caminito (daytime only)","si_tag":"culture","tier":"essential","commission_path":"guided-tour affiliate / DMC","source":"https://solsalute.com/blog/is-buenos-aires-safe-for-tourists/","hook":"The painted tin tenements, birthplace of tango and of Boca Juniors — a guided daytime visit only","si":"culture","blurb":"The painted tin tenements, birthplace of tango and of Boca Juniors — a guided daytime visit only","commission":"guided-tour affiliate / DMC"},{"name":"Tigre Delta day","si_tag":"culture","tier":"essential","commission_path":"activities affiliate / DMC day-tour","source":"https://luxurylatinamerica.com/blog/2023/03/13/day-trips-from-buenos-aires/","hook":"An hour north, the Paraná Delta''s maze of channels and stilt-houses","si":"culture","blurb":"An hour north, the Paraná Delta''s maze of channels and stilt-houses","commission":"activities affiliate / DMC day-tour"},{"name":"Pampas estancia day — San Antonio de Areco (gaucho)","si_tag":"culture","tier":"comfort","commission_path":"DMC / MoR estancia booking","source":"https://solsalute.com/blog/best-buenos-aires-day-trips/","hook":"~1½ hrs out onto the grasslands to a working ranch: horseback, all-afternoon asado, folklore, and gaucho tradition","si":"culture","blurb":"~1½ hrs out onto the grasslands to a working ranch: horseback, all-afternoon asado, folklore, and gaucho tradition","commission":"DMC / MoR estancia booking"},{"name":"Argentine Open Polo (November, Palermo)","si_tag":"culture","tier":"premier","commission_path":"DMC / hospitality-package MoR","source":"https://www.theaircharterjournal.com/air-charter-journal/argentine-polo-open-2025","hook":"The world''s most prestigious polo championship, at the \"Cathedral of Polo\" — grandstand and hospitality seats are a marquee November draw","si":"culture","blurb":"The world''s most prestigious polo championship, at the \"Cathedral of Polo\" — grandstand and hospitality seats are a marquee November draw","commission":"DMC / hospitality-package MoR"},{"name":"Colonia del Sacramento day trip (Uruguay)","si_tag":"culture","tier":"comfort","commission_path":"ferry affiliate + DMC day-tour","source":"https://luxurylatinamerica.com/blog/2023/03/13/day-trips-from-buenos-aires/","hook":"Ferry across the Río de la Plata to a UNESCO colonial town — the calm counterpoint to BA","si":"culture","blurb":"Ferry across the Río de la Plata to a UNESCO colonial town — the calm counterpoint to BA","commission":"ferry affiliate + DMC day-tour"}],"faq":[{"q":"When is the best time to visit Buenos Aires for a honeymoon?","a":"The spring and fall shoulders — October–November and March–April — are the sweet spot, with mild 18–26 °C days and thinner crowds than the hot, humid summer. November is the standout: the jacarandas bloom lilac across Recoleta''s boulevards and the Argentine Open Polo fills Palermo, so treat November premium beds as a 3–6 month advance book.","source":"lonelyplanet.com, Accessed 2026-07-07","si_tag":"romance"},{"q":"What are the must-see cultural sites in Buenos Aires?","a":"Start with Recoleta Cemetery — 6,400+ statues and crypts, including Evita Perón''s tomb, with free Spanish guided tours Tue–Sun — then Teatro Colón, one of the great opera houses of the world, and a daytime visit to La Boca''s Caminito, birthplace of tango. San Telmo''s Sunday feria on Calle Defensa rounds out the heritage circuit.","source":"buenosairesfreewalks.com, Accessed 2026-07-07","si_tag":"culture"},{"q":"What is a puerta cerrada (closed-door) restaurant?","a":"They are secret chef''s-home supper clubs, a Porteño institution. Fogón Asado runs a Michelin-recommended 9-course asado tasting for ~35 guests with optional Argentine wine pairings, while Casa Saltshaker (est. 2005) does intimate shared-table five-course dinners with Malbec-vs-Patagonian-pinot flights — one of the city''s oldest such houses.","source":"theculturetrip.com, Accessed 2026-07-07","si_tag":"culinary"},{"q":"Is Buenos Aires safe right now?","a":"Yes. Argentina is at U.S. State Department Level 1 \"Exercise Normal Precautions\" — rated in the same top tier as Japan and New Zealand — and the real risk in BA is urban petty crime, theft by distraction rather than force, which is predictable and avoidable. The single regional exception, a Level 2 for the city of Rosario, is not on a BA itinerary.","source":"travel.state.gov, Accessed 2026-07-07","si_tag":"safety"},{"q":"What''s the real risk to plan for in Buenos Aires?","a":"Snatch-and-grab theft, not violence. BA''s characteristic street crime is motochorros (motorcycle thieves) and distraction scams, with roughly 90% of motochorro snatchings happening at traffic lights; keep your phone off café-table edges and use vetted radio-taxi or ride-apps. La Boca is daytime-and-Caminito only — arrive by taxi and leave before dark.","source":"secretsofbuenosaires.com, Accessed 2026-07-07","si_tag":"safety"},{"q":"Do I need travel insurance for Argentina?","a":"Treat it as required and always buy it. Under Decree 366/2025, effective 2025-07-01, non-resident travelers were required to carry travel medical insurance covering emergency care, hospitalization, evacuation and repatriation, with airlines confirming at check-in. One December-2025 secondary source reported the rule may have been suspended or modified (unverified and conflicting), so verify current enforcement at booking.","source":"globalrescue.com, Accessed 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Buenos Aires Travel Guide — Tango, Steak & Boutique Hotels | TravelWell","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","search_language":"es-AR","long_tail_en":["things to do in Buenos Aires","best tango show Buenos Aires","closed-door restaurants Buenos Aires","Buenos Aires honeymoon","best time to visit Buenos Aires","Recoleta cemetery Evita","Tigre Delta day trip","San Antonio de Areco estancia","Buenos Aires luxury hotels","is Buenos Aires safe"],"local_keywords":["qué hacer en Buenos Aires","show de tango Buenos Aires","mejores parrillas Buenos Aires","puertas cerradas Buenos Aires","Cementerio de la Recoleta Evita","estancia San Antonio de Areco","escapada al Delta del Tigre","hoteles de lujo Buenos Aires","Abierto Argentino de Polo","mejor época para visitar Buenos Aires"],"hreflang":["en","es-AR"]},"booking":null,"si_checklist_25":null,"sis_present":null,"ultra":[{"name":"Four Seasons Hotel Buenos Aires + La Mansion","barrio":"Recoleta","tier":"ultra","earning":"FS Preferred Partner / Virtuoso — commission + amenities (UNVERIFIED %)"},{"name":"Alvear Palace Hotel","barrio":"Recoleta","tier":"ultra","earning":"Virtuoso / LHW — commission + amenities (UNVERIFIED %)"},{"name":"Palacio Duhau — Park Hyatt Buenos Aires","barrio":"Recoleta","tier":"ultra","earning":"Hyatt Prive / Virtuoso — commission + amenities (UNVERIFIED %)"},{"name":"Faena Hotel Buenos Aires","barrio":"Puerto Madero","tier":"ultra","earning":"Virtuoso / brand luxury — commission + amenities (UNVERIFIED %)"}],"source_verified":null,"hero":{"query":"Buenos Aires, Argentina, Argentina"},"geo":{"lat":-34.6037,"lng":-58.3816}}'::jsonb, 14),
  ('cabo-pulmo-mexico', '10S', 'Cabo Pulmo', 'Mexico', 'The Sea of Cortez, recovered **TravelWell', 'live', 'verified', 'mountainValley', 'Baja California Sur (Los Cabos & La Paz)', '{"expedition","diveglobal"}', '{}', '{"essential","premier"}', null, null, '{"key_facts":["Federally protected National Marine Park since June 5, 1995; ~71 km2 fully protected (Source: en.wikipedia.org/wiki/Cabo_Pulmo_National_Park, 2026-07-04)","463% total fish-biomass increase, ~11x top-predator jump by 2009 — most successful no-take recovery measured (Source: ocean.si.edu, 2026-07-04)","Only living hard-coral reef in the Sea of Cortez; UNESCO WHS 2005, Ramsar 2008 (Source: en.wikipedia.org, 2026-07-04)","CONANP no-take rules: guide-led 6:1, no touching, gloves banned, licensed pangas only (Source: mexicotraveladventure.com, 2026-07-04)","Off-grid village; ~2-3 h drive north of SJD / Los Cabos; eco-cabañas only, no luxury hotels (Source: sallysees.com, 2026-07-04)"],"safety":{"emergency":"911","nearest_trauma":"Cabo San Lucas / San Jose del Cabo (Los Cabos), ~2-3 h by road; La Paz alternative","advisory_level":"L2","advisory_note":"Baja California Sur US Level 2 (Exercise Increased Caution), May 29, 2026 — freely bookable, disclose L2, no hold","malaria":"none","dengue":"present in Baja California Sur; use repellent","water":"bottled/purified","hurricane":"May 15-Nov 30, peak Aug-Oct","remote_medevac":"off-grid; no chamber/hospital in village; multi-hour ground evac to Los Cabos"},"timing":{"peak":"Jul-Nov (best visibility, bull-shark aggregation)","shoulder":"Apr-Jun, late fall","green":"Dec-Feb (coolest water, wind days)","booking_window_lead_time":"2-4 months (capped dive slots + tiny bed inventory)","out_of_season_fill":"winter dive-and-stay packages; East Cape / Los Cabos day-trip combos","holiday_event_peaks":["US/Canada summer holidays","Los Cabos Dec-Apr high-season spillover"],"campaign_start_trigger":"late spring for summer-fall dive peak; Los Cabos winter high season for day-trip capture"},"jewels":[{"si_tag":"expedition","status":"live","tier":"essential","commission":"operator agreement","name":"Pulmo reef recovery dive","si":"expedition"},{"si_tag":"expedition","status":"live","tier":"premier","commission":"operator agreement","name":"Bull-shark aggregation dive","si":"expedition"},{"si_tag":"expedition","status":"live","tier":"essential","commission":"operator + DMC","name":"Protected-reef snorkel","si":"expedition"},{"si_tag":"expedition","status":"live","tier":"premier","commission":"operator agreement","name":"Sea-lion / offshore pinnacle dives","si":"expedition"},{"si_tag":"diveglobal","status":"future","tier":"premier","commission":"operator; stay direct","name":"Multi-day Cabo Pulmo dive-and-stay","si":"diveglobal"}],"faq":[{"q":"Is Cabo Pulmo worth diving, and what will I see?","a":"Yes — it is arguably the Sea of Cortez''s best dive, because protection worked: total fish biomass rebounded 463% by 2009 on the Gulf''s only living hard-coral reef. Expect schooling jacks, groupers and rays, and in warm summer–fall water a bull-shark aggregation.","source":"ocean.si.edu / divearoo.com, 2026-07-04","si_tag":"expedition"},{"q":"Do I need to be certified, and can non-divers go?","a":"You dive within your card with a mandatory park guide (max 6 divers each), and non-divers can snorkel the same no-take reef. The rules are strict — no gloves, no touching, licensed pangas only — and enforced; break them and you can be pulled from the water.","source":"mexicotraveladventure.com, 2026-07-04","si_tag":"diveglobal"},{"q":"Can couples make a romantic escape of Cabo Pulmo?","a":"Only if \"romantic\" means off-grid and simple — there is no resort or spa layer. Lodging is solar eco-cabañas and a tiny villa cluster (~5 villas), which suits low-key couples; anyone wanting branded luxury bases in Los Cabos or the East Cape and day-trips in.","source":"sallysees.com / cabopulmo.com, 2026-07-04","si_tag":"romance"},{"q":"Is Cabo Pulmo safe to visit right now?","a":"Yes — freely bookable. Baja California Sur carries a US State Dept Level 2 \"Exercise Increased Caution\" (May 29, 2026) and is one of Mexico''s safer states; the real caveat here is remoteness, not crime.","source":"travel.state.gov, 2026-05-29","si_tag":"safety"},{"q":"Is diving here dangerous — what''s the real risk?","a":"The gatekeeper is medevac distance, not the diving itself. Cabo Pulmo is off-grid with no chamber or hospital in the village; the nearest recompression chamber and trauma care are ~2–3 hours away in Los Cabos, so dive conservatively, carry DAN cover, and observe 18–24 h no-fly before an SJD departure.","source":"sssnetwork.com / dan.org, 2026-07-04","si_tag":"safety"}],"seo":{"meta_title":"Cabo Pulmo Diving — Sea of Cortez No-Take Reef | TravelWell.World","meta_description":"Dive Cabo Pulmo, the most-recovered no-take marine reserve in the Sea of Cortez. Guided park dives, no-touch rules, eco-cabaña stays, Los Cabos gateway logistics.","primary_keywords":["Cabo Pulmo diving","Cabo Pulmo National Park","Cabo Pulmo snorkeling","Sea of Cortez reef"],"long_tail":["best time to dive Cabo Pulmo","Cabo Pulmo bull shark season","how to get to Cabo Pulmo from Los Cabos","Cabo Pulmo eco cabañas"],"search_language":"es-MX","local_keywords":["buceo Cabo Pulmo","Parque Nacional Cabo Pulmo","arrecife de coral Mar de Cortes","snorkel Cabo Pulmo","reserva marina sin pesca","cabanas ecologicas Cabo Pulmo"],"hreflang":["en","es-MX"],"jsonld_type":"TouristAttraction","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":["expedition","diveglobal"],"ultra":[{"what":"Four Seasons Los Cabos at Costa Palmas / Amanvari (East Cape, Los Cabos) as luxury base for a Cabo Pulmo dive charter","why_ultra":"largest swimmable beach + only private marina in Los Cabos; Amanvari is first Aman in Mexico (spring 2026)","earning":"on application / via host-Virtuoso","virtuoso_value_add":"resort credit, upgrade, breakfast; private guide for Pulmo run","mor":"resale via host-Virtuoso only; Cabo Pulmo itself is NOT an ultra stay — nearest ultra is Los Cabos"}],"source_verified":"2026-07-04","hero":{"query":"Cabo Pulmo, Mexico"},"geo":{"lat":23.4433,"lng":-109.4283}}'::jsonb, 15),
  ('cabo-san-lucas-mexico', '10S', 'Cabo San Lucas', 'Mexico', 'Cabo San Lucas Socorro liveaboard', 'live', 'verified', 'oceanAerial', 'Baja California Sur (Los Cabos & La Paz)', '{"liveaboard","expedition","ocean","ultra"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":["Socorro/Revillagigedo liveaboards depart Cabo (~250nm / ~24h crossing), Nov-Jun; giant Pacific mantas + up to 10 shark species","Whale-watching Dec 15-Apr 15 (humpback + gray), peak Jan-Mar","Bisbee''s Black & Blue marlin tournament: 3rd week of October, 2026 = Oct 19-24, purse >$11.5M","One of North America''s densest ultra-luxury resort clusters (multiple Forbes Five-Star)","Pacific hurricane/chubasco season Jun-Nov, peak Sep-Oct"],"safety":{"emergency":"911","hospital":"Los Cabos private: AmeriMed, Blue Medical, Hospital H+ Los Cabos (Sechrist hyperbaric chamber) - VERIFY numbers; serious DCI/trauma may US air-evac","recompression_chambers":[{"name":"BMM Cabo San Lucas (Buceo Medico Mexicano / SSS Network)","address":"Local E-15/16/17, Plaza Las Glorias, Marina Cabo San Lucas, BCS 23410","phone":"VERIFY (SSS listing shows local 143-3666)","network":"SSS Network"},{"name":"Hospital H+ Los Cabos","note":"Sechrist hyperbaric chamber"},{"name":"PRMEDICA (San Jose del Cabo)","note":"hyperbaric chamber"}],"dan_emergency":"+1-919-684-9111","advisory_level":"L2","malaria":"none","yellow_fever":"not required","dengue":"low","water":"bottled/purified only","hurricane":"Pacific Jun-Nov (peak Sep-Oct)","dive_no_fly":"12h single / 18h multi-day / 24h deco (DAN); use 18-24h after a Socorro liveaboard","socorro_remote_flag":"no chamber at Revillagigedo; ~24h to Cabo chamber - conservative profiles + DAN evac cover mandatory"},"timing":{"peak":"Nov-Apr (dry); whale season Dec 15-Apr 15; Socorro liveaboard Nov-Jun; NYE + Spring Break premium","shoulder":"May and October (October carries Bisbee''s crowd)","green":"Jul-Sep hot/humid, Pacific hurricane/chubasco season Jun-Nov (peak Sep-Oct); Socorro closed","booking_lead":"Socorro liveaboards 6-12+ months ahead; Bisbee''s-week lodging + charters months ahead; NYE/Spring-Break villas + ultra suites months ahead","off_season_specials":"green-summer value (lowest rates, warm sea, dorado/tuna fishing) to price-sensitive couples/families + mandatory hurricane trip insurance","event_peaks":["Bisbee''s Black & Blue Oct 19-24 2026 ($11.5M+ purse)","Christmas/NYE premium","US Spring Break (Mar)","whale season Dec 15-Apr 15"],"campaign_start":"Socorro campaign 9-12 months out; whale-season push Aug-Oct; Bisbee''s/sportfishing micro-campaign spring-summer; green-value push May-Jun"},"jewels":[{"name":"Socorro/Revillagigedo giant-manta liveaboard","si_tag":"Dive Liveaboards","status":"live","hook":"giant Pacific mantas approach + stay; up to 10 shark species, whale sharks, humpbacks","bookable_category":"liveaboard","tier":"premier","commission_path":"Aggressor/liveaboard reseller = Commissioned Agent on application (TCI moat)","source":"https://nautilusliveaboards.com/socorro/","si":"liveaboard","blurb":"giant Pacific mantas approach + stay; up to 10 shark species, whale sharks, humpbacks","commission":"Aggressor/liveaboard reseller = Commissioned Agent on application (TCI moat)"},{"name":"Roca Partida (Socorro site)","si_tag":"Dive Liveaboards","status":"live","hook":"isolated open-ocean pinnacle, silvertips + Galapagos sharks in the current","bookable_category":"liveaboard itinerary","tier":"premier","commission_path":"liveaboard reseller = Commissioned Agent on application","source":"https://www.bluewaterdivetravel.com/destination/socorro-island-diving","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"isolated open-ocean pinnacle, silvertips + Galapagos sharks in the current","when":"Nov-Apr","commission":"liveaboard reseller = Commissioned Agent on application"},{"name":"Gray + humpback whale-watching","si_tag":"Global Expedition Adventures","status":"live","hook":"humpback breaching/mating + gray whale calves","bookable_category":"whale-watch tour","tier":"essential","commission_path":"DMC + Viator/GYG affiliate","source":"https://www.visitloscabos.travel/blog/post/whale-watching-in-los-cabos-2025-the-ultimate-guide-to-an-unforgettable-season/","si":"expedition","blurb":"humpback breaching/mating + gray whale calves","commission":"DMC + Viator/GYG affiliate"},{"name":"Bisbee''s Black & Blue marlin sportfishing","si_tag":"Ocean Adventures","status":"future","hook":"world''s richest billfish tournament; Marlin Capital of the World","bookable_category":"sportfishing charter","tier":"comfort","commission_path":"charter/DMC commission on application","source":"https://bisbees.com/tournaments/bisbees-black-blue","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"world''s richest billfish tournament; Marlin Capital of the World","when":"Nov-Apr","commission":"charter/DMC commission on application"},{"name":"Land''s End / El Arco + Pelican Rock snorkel","si_tag":"Ocean Adventures","status":"future","hook":"iconic granite arch + easy snorkel at the peninsula tip","bookable_category":"boat/snorkel tour","tier":"essential","commission_path":"Viator/GYG affiliate + DMC","source":"https://www.cabovillas.com/yacht-tours","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"iconic granite arch + easy snorkel at the peninsula tip","when":"Nov-Apr","commission":"Viator/GYG affiliate + DMC"},{"name":"Superyacht + private-jet charter","si_tag":"Luxury","status":"future","hook":"jet-to-yacht for the ultra client","bookable_category":"charter","tier":"ultra","commission_path":"charter/DMC commission on application","source":"https://www.cabovillas.com/jet-charters","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Luxury","blurb":"jet-to-yacht for the ultra client","when":"Nov-Apr","commission":"charter/DMC commission on application"}],"faq":[{"q":"When can I dive Socorro from Cabo, and what will I see?","a":"Socorro runs by liveaboard only, roughly November–June, on a ~24-hour crossing from Cabo — there is no day-boat option. The draw is giant Pacific mantas that approach and stay through whole dives, up to 10 shark species, dolphins, whale sharks (Nov–Dec) and humpbacks (Jan–Mar). Book berths 6–12+ months out.","source":"bluewaterdivetravel.com, 2026-07-04","si_tag":"liveaboard"},{"q":"When is whale season in Cabo?","a":"December 15 to April 15, with peak sightings January–March. Humpbacks breach and mate while gray whales pass with newborn calves, all on boat-based tours out of Cabo.","source":"visitloscabos.travel, 2026-07-04","si_tag":"expedition"},{"q":"When is Bisbee''s, and is Cabo really the \"Marlin Capital\"?","a":"Bisbee''s Black & Blue runs the third week of October — Oct 19–24 in 2026 — with a purse topping $11.5 million, and Cabo backs the \"Marlin Capital\" tag with year-round blue and black marlin, dorado and tuna. Tournament-week lodging and charters sell out months ahead.","source":"bisbees.com, 2026-07-04","si_tag":"ocean"},{"q":"Is Cabo good for a honeymoon, and where''s the top end?","a":"Yes — it is one of North America''s densest ultra clusters, with multiple Forbes Five-Star flags. The honeymoon flagships are Las Ventanas al Paraíso (Rosewood) and One&Only Palmilla; Waldorf Astoria Pedregal, Montage and Chileno Bay sit alongside on the corridor''s rare swimmable coves.","source":"forbes.com, 2026-07-04","si_tag":"romance"},{"q":"Is Cabo San Lucas safe right now?","a":"Yes — freely bookable. Baja California Sur carries a US State Dept Level 2 \"Exercise Increased Caution\" (May 29, 2026) — the same tier the US assigns France, Italy and the UK — and BCS is among Mexico''s safer states.","source":"travel.state.gov, 2026-05-29","si_tag":"safety"},{"q":"Is diving Socorro dangerous?","a":"It is advanced, remote diving — manageable with discipline. Socorro has strong currents, deep pelagic sites and no chamber at the archipelago; a hit means a ~24-hour steam back to Cabo''s chamber. Dive within your certification, follow the boat''s conservative plan, carry DAN evacuation cover, and wait 18–24 h before flying home.","source":"bluewaterdivetravel.com / dan.org, 2026-07-04","si_tag":"safety"}],"seo":{"meta_title":"Cabo San Lucas: Socorro Liveaboards, Whales & Ultra Cabo","meta_description":"Cabo San Lucas is the port where Socorro''s giant-manta liveaboards begin - plus whale season, Bisbee''s marlin, and one of North America''s densest ultra-luxury clusters.","slug":"cabo-san-lucas-mexico","primary_keyword":"Cabo San Lucas Socorro liveaboard","long_tail":["Socorro Revillagigedo liveaboard from Cabo","Cabo whale watching season","Bisbee''s Black and Blue 2026 dates","Cabo San Lucas luxury resorts Virtuoso","giant manta ray diving Mexico"],"search_language":["en","es-MX"],"local_keywords":["buceo liveaboard Socorro desde Cabo San Lucas","avistamiento de ballenas Los Cabos","torneo de marlin Bisbee''s Black and Blue","mantarraya gigante Revillagigedo","villas de lujo en Cabo San Lucas","resorts cinco estrellas Los Cabos"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"liveaboard","status":"live","note":"Socorro/Revillagigedo liveaboards depart Cabo San Lucas, ~24h crossing, Nov-Jun season"},{"si":"expedition","status":"live","note":"gray + humpback whale-watching Dec 15-Apr 15"},{"si":"ocean","status":"future"},{"si":"ultra","status":"future"}],"ultra":[{"name":"Waldorf Astoria Los Cabos Pedregal","why_ultra":"top overall Los Cabos rec; cliffside Pedregal, private tunnel, plunge-pool suites","earning":"Virtuoso/Hilton Impresario preferred + commission on application","virtuoso_value_add":"upgrade, breakfast, resort credit, early check-in/late check-out (verify)","mor":"agent-of-record","price_tier":"ultra"},{"name":"One&Only Palmilla","why_ultra":"timeless glamour, personalized service, family + honeymoon icon","earning":"Virtuoso preferred + commission on application","virtuoso_value_add":"upgrade, breakfast, credit, VIP welcome (verify)","mor":"agent-of-record","price_tier":"ultra"},{"name":"Las Ventanas al Paraiso, A Rosewood Resort","why_ultra":"the Cabo honeymoon flagship, Rosewood service, artisan interiors","earning":"Rosewood Elite / Virtuoso preferred + commission on application","virtuoso_value_add":"upgrade, breakfast, spa/resort credit (verify)","mor":"agent-of-record","price_tier":"ultra"},{"name":"Montage Los Cabos","why_ultra":"rated best high-end hotel in Los Cabos, rare swimmable cove","earning":"Montage / Virtuoso preferred + commission on application","virtuoso_value_add":"upgrade, breakfast, credit (verify)","mor":"agent-of-record","price_tier":"ultra"},{"name":"Chileno Bay Resort & Residences (Auberge)","why_ultra":"99-key Auberge on a protected swimmable cove","earning":"Auberge / Virtuoso preferred + commission on application","virtuoso_value_add":"upgrade, breakfast, credit (verify)","mor":"agent-of-record","price_tier":"ultra"},{"name":"Esperanza (Auberge)","why_ultra":"Punta Ballena oceanfront, timeless elegance + culinary","earning":"Auberge / Virtuoso preferred + commission on application","virtuoso_value_add":"upgrade, breakfast, credit (verify)","mor":"agent-of-record","price_tier":"ultra"},{"name":"Four Seasons Cabo del Sol","why_ultra":"Four Seasons service, foodie-led resort","earning":"FSPP / Virtuoso preferred + commission on application","virtuoso_value_add":"upgrade, breakfast, credit (verify)","mor":"agent-of-record","price_tier":"ultra"},{"name":"Nobu Hotel Los Cabos","why_ultra":"Nobu design-luxury + signature restaurant, celebrity draw","earning":"preferred-partner + commission on application","virtuoso_value_add":"verify current program","mor":"agent-of-record","price_tier":"ultra"},{"name":"Fully-staffed ultra villa buyout + superyacht/jet charter","why_ultra":"private-estate + LUX cross-cut (NetJets/VistaJet jet-to-yacht)","earning":"villa-agency/charter commission on application (no net-rate resale)","virtuoso_value_add":"attach Virtuoso hotel pre/post-stay","mor":"clean agent-side; red-flag villa-inventory mark-up","price_tier":"ultra"}],"source_verified":"2026-07-04","hero":{"query":"Cabo San Lucas, Mexico"},"geo":{"lat":22.8905,"lng":-109.9167}}'::jsonb, 16),
