  ('costalegre-mexico', '10S', 'Costalegre (Costa Alegre)', 'Mexico', 'Costalegre Mexico', 'live', 'verified', 'tropicalBeach', 'Jalisco (Puerto Vallarta & Guadalajara)', '{"tropical","romance","ultra","ocean"}', '{"tropical"}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":["~200 mi undeveloped Pacific coast between Puerto Vallarta and Manzanillo; PV->Barra de Navidad ~4-hr drive on Hwy 200","Five littoral areas: Bahia de Chamela, Costa Careyes, Cuixmala, Bahia de Tenacatita, Bahia de Navidad","Chamela-Cuixmala Biosphere Reserve ~32,000 acres tropical dry forest; UNAM research station since 1971","Humpback whales migrate Dec-Mar; Chamela islands (Isla Cocinas/Pajarera) reachable by boat","Ultra enclaves Careyes, Cuixmala, Las Alamandas with private airstrips; Chalacatepec airport completed Mar 2024 (operational status pending)"],"safety":{"emergency":"911","hospital":"remote coast; serious cases route to Manzanillo (~1.5 hr from Careyes area) or Puerto Vallarta (~2-4 hr north); carry travel-medical + air-evac insurance","advisory_level":"L3","book_enabled":false,"tourist_zone_carveout":"none (southern Jalisco coast NOT a named carve-out)","air_access_verified":"Manzanillo (ZLO, Colima) / PVR - not into a named carve-out; new Chalacatepec airport planned (verify); private airstrips at Careyes/Cuixmala/Las Alamandas - founder-review flag","founder_flag":"private-airstrip ''resort-airstrip private-access'' clean-pass class - flag for founder review; content-only until founder rules on carve-out","malaria":"low - mosquito avoidance (not prophylaxis) for Jalisco coastal lowlands below 1,000 m","dengue":"circulates (Jalisco cases 2025; peak May-Nov) - daytime repellent","water":"drink bottled/purified","hurricane":"May-Nov - trip insurance for summer/fall","remote":"limited services between towns; carry water/fuel/meds; do NOT drive secondary roads after dark (advisory warning)","road_transfer":"transfers pass through non-carve-out southern Jalisco - the hold reason; daylight main-highway DMC transfers only if ever activated","dive":"nearest hyperbaric chambers in Puerto Vallarta and Manzanillo (1.5-4 hr away) - conservative profiles, DAN insurance, strict no-fly interval"},"timing":{"peak":"Nov-Apr (dry season, calm, humpbacks Dec-Mar, Careyes polo/events season, ultra-villa demand highest)","shoulder":"May & late Oct (warm, quieter, pre/post rains)","green":"Jul-Oct (hot/humid, emerald hills, hurricane window May-Nov, softer rates)","event_peak":"Careyes polo late-Nov->end-Apr (Agua Alta Cup at Easter); Ondalinda x Careyes Nov 12-15 2026","booking_window_lead_time":"ultra villas for Christmas-New Year/winter holidays book 6-12 months ahead, contracted direct on application; green-season windows far shorter","out_of_season_fill_the_beds":"green season (Jul-Oct) eco/wildlife (turtle nesting, biosphere), sportfishing, storm-quiet villa buyouts at softer rates - the ''secret season''","holiday_event_peaks":"Christmas-New Year (ultra premium), Semana Santa/Easter (Agua Alta Cup polo), Ondalinda (mid-Nov), winter polo season","campaign_start_trigger":"content-only - no campaign; if founder rules carve-out for private-airstrip enclaves, open winter/holiday villa campaigns in spring for following Nov-Apr peak (6-12-mo lead)","sources":["https://mexiconewsdaily.com/travel/an-insiders-guide-to-the-perfect-weekend-in-costalegre/","https://www.ondalinda.com/festivals/careyes/","https://www.costalegre.ca/"]},"jewels":[{"name":"Careyes clifftop Castles & Iconic Villas","si_tag":"Luxury / Ultra-Luxury","status":"future","tier":"ultra","bookable":"Careyes reservations / villa specialist","commission_path":"on application / villa specialist","source":"https://careyes.com/","timing":"year-round","timing_type":"ALWAYS-ON","hook":"staffed clifftop villas with moat-like infinity pools; Heidi Klum married here, celebrities vacation here","si":"ultra","blurb":"staffed clifftop villas with moat-like infinity pools; Heidi Klum married here, celebrities vacation here","when":"year-round","commission":"on application / villa specialist"},{"name":"Cuixmala (Casa Cuixmala suites / hillside villas)","si_tag":"Luxury / Ultra-Luxury","status":"future","tier":"ultra","bookable":"Cuixmala direct / luxury DMC","commission_path":"on application","source":"https://cuixmala.com/","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Goldsmith''s 25,000-acre reserve estate — zebras, nesting turtles, total seclusion","si":"ultra","blurb":"Goldsmith''s 25,000-acre reserve estate — zebras, nesting turtles, total seclusion","when":"Nov-Apr","commission":"on application"},{"name":"Las Alamandas","si_tag":"Luxury / Ultra-Luxury","status":"future","tier":"ultra","bookable":"Las Alamandas direct / DMC","commission_path":"on application","source":"https://www.alamandas.com/","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"18 suites across 8 villas, gated ultra-boutique. On application","si":"ultra","blurb":"18 suites across 8 villas, gated ultra-boutique. On application","when":"Nov-Apr","commission":"on application"},{"name":"Chamela Bay islands (Isla Cocinas / Isla Pajarera)","si_tag":"Tropical Islands","status":"future","tier":"essential","bookable":"local panga boat tour (content-only)","commission_path":"local operator (n/a while content-only)","source":"https://mexiconewsdaily.com/travel/an-insiders-guide-to-the-perfect-weekend-in-costalegre/","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","when":"Nov-Apr","commission":"local operator (n/a while content-only)"},{"name":"Tenacatita Bay","si_tag":"Tropical Islands","status":"future","tier":"comfort","bookable":"local operators (content-only)","commission_path":"local (content-only)","source":"https://mexiconewsdaily.com/travel/an-insiders-guide-to-the-perfect-weekend-in-costalegre/","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"is famed for clear water, snorkeling, kayaking and paddleboarding; Chamela Bay is dotted with marine-reserve islands reachable by boat tour","si":"tropical","blurb":"is famed for clear water, snorkeling, kayaking and paddleboarding; Chamela Bay is dotted with marine-reserve islands reachable by boat tour","when":"Nov-Apr","commission":"local (content-only)"},{"name":"Barra de Navidad lagoon village","si_tag":"Romance & Honeymoons","status":"future","tier":"premier","bookable":"Grand Isla Navidad Resort / boutique (content-only)","commission_path":"OTA/DMC (content-only for the coast)","source":"https://www.mexicotravelandleisure.com/blog/barra-de-navidad-mexico/","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"colonial-shipyard fishing town with a scenic lagoon and slow small-town charm — an authentic couples'' base","si":"romance","blurb":"colonial-shipyard fishing town with a scenic lagoon and slow small-town charm — an authentic couples'' base","when":"Nov-Apr","commission":"OTA/DMC (content-only for the coast)"},{"name":"Winter humpback whale coast (Dec-Mar)","si_tag":"Ocean Adventures","status":"future","tier":"essential","bookable":"local whale/boat tour (content-only)","commission_path":"local operator (content-only)","source":"https://www.costalegre.ca/","si":"ocean","commission":"local operator (content-only)"}],"faq":[{"q":"Can I book Costalegre through TravelWell right now?","a":"No — it is content-only. Jalisco sits at US State Dept Level 3 \"Reconsider Travel\" (May 29, 2026), and the advisory''s four named no-restriction carve-outs (Guadalajara Metro, Puerto Vallarta, Chapala, Ajijic) do not include the southern-Jalisco Costalegre coast, so book_enabled=FALSE.","source":"travel.state.gov, 2026-05-29","si_tag":"safety"},{"q":"What''s the real risk to plan for on Costalegre?","a":"The road transfer, and the remoteness. Ground access runs through non-carve-out southern Jalisco on Highway 200 and secondary roads, and the advisory warns against secondary highways after dark — the hold reason. The coast is remote: serious cases route ~1.5 hr to Manzanillo or 2–4 hr to Puerto Vallarta, so air-evac insurance is essential.","source":"travel.state.gov / lprluxury.com, 2026-07-04","si_tag":"safety"},{"q":"What makes Costalegre a true ultra coast?","a":"Three private enclaves with their own airstrips. Careyes (clifftop castles + ~50 staffed villas), Cuixmala (a ~25,000-acre Goldsmith biosphere estate) and Las Alamandas (an 18-suite gated boutique) form one of Mexico''s most private ultra nodes — the private-air arrival is the crux of a possible future clean-pass.","source":"cuixmala.com / careyes.com, 2026-07-04","si_tag":"ultra"},{"q":"What are the best beaches and islands here?","a":"Chamela Bay and Tenacatita. Chamela is dotted with marine-reserve islets (Isla Cocinas, Isla Pajarera) reachable by panga, and Tenacatita (~30 min north of Barra de Navidad) is famed for clear, calm water for snorkel, kayak and SUP — the calmest bays on a ~200-mile coast.","source":"mexiconewsdaily.com, 2026-07-04","si_tag":"tropical"},{"q":"When can I see whales on Costalegre?","a":"December to March. Humpbacks migrate and breach offshore along the whole coast in the dry winter season — the same window as peak ultra-villa demand — while the Chamela–Cuixmala biosphere adds turtle nesting and dry-forest wildlife. Keep a regulated distance on any boat tour.","source":"costalegre.ca, 2026-07-04","si_tag":"ocean"}],"seo":{"meta_title":"Costalegre Mexico: Careyes, Cuixmala & the Wild Jalisco Coast","meta_description":"Costalegre — ~200 mi of undeveloped Jalisco Pacific coast between Puerto Vallarta and Manzanillo: Careyes, Cuixmala, Las Alamandas, Tenacatita, Barra de Navidad. Ultra villas, whales, biosphere.","slug":"costalegre-mexico","primary_keyword":"Costalegre Mexico","long_tail":["Costalegre luxury villas","Careyes Cuixmala Las Alamandas","Costalegre vs Puerto Vallarta","Tenacatita Bay snorkeling","Barra de Navidad travel guide","Costalegre whale watching Dec-Mar"],"search_language":["en","es-MX"],"local_keywords":["Costalegre Jalisco","villas de lujo Careyes","Cuixmala reserva biosfera","Las Alamandas Costalegre","Bahia Tenacatita snorkel","Barra de Navidad que hacer","avistamiento de ballenas Costalegre"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"tropical","status":"future"},{"si":"romance","status":"future"},{"si":"Luxury / Ultra-Luxury","status":"future"},{"si":"ocean","status":"future"}],"ultra":[{"name":"Cuixmala","posture":"Goldsmith ~25,000-acre biosphere estate; suites/villas/casitas; private airstrip","price_tier":"ultra","earning":"on application / luxury DMC (Journey Mexico) / villa specialist","virtuoso_value_add":"likely via luxury-DMC channel - verify at contract","mor":"no net-rate resale","book_gated":"founder carve-out decision (private-airstrip clean-pass class)","source":"https://cuixmala.com/"},{"name":"Careyes (Casitas / Villas / Castles)","posture":"Brignone 1968 enclave; hotel + casitas + ~50 villas + clifftop castles; polo/sailing/Ondalinda; private-air (Chamela strip ~15 min / Chalacatepec ~40 min)","price_tier":"ultra","earning":"on application / villa specialist","virtuoso_value_add":"verify at contract","mor":"no net-rate resale","book_gated":"founder carve-out decision","source":"https://careyes.com/"},{"name":"Las Alamandas","posture":"Isabel Goldsmith 18-suite gated ultra-boutique on private bay; own 3,300-ft airstrip (currently unavailable - use Chamela strip 15 min)","price_tier":"ultra","earning":"on application / DMC","virtuoso_value_add":"likely via luxury-DMC channel - verify","mor":"no net-rate resale","book_gated":"founder carve-out decision","source":"https://www.alamandas.com/"},{"name":"El Careyes (Club & Residences)","posture":"beachfront club/residences arm of Careyes enclave","price_tier":"luxury","earning":"on application","virtuoso_value_add":"verify at contract","mor":"no net-rate resale","book_gated":"founder carve-out decision","source":"https://careyes.com/"}],"source_verified":"2026-07-04","hero":{"query":"Costalegre (Costa Alegre), Mexico"},"geo":{"lat":19.44,"lng":-105.04}}'::jsonb, 29),
  ('cozumel-mexico', '10S', 'Cozumel', 'Mexico', 'Cozumel drift diving', 'live', 'verified', 'oceanAerial', 'Quintana Roo (Cancún & Riviera Maya)', '{"diveglobal","liveaboard","ocean"}', '{}', '{"essential","comfort","premier"}', null, null, '{"key_facts":["Reefs sit on the Mesoamerican Barrier Reef (Great Mayan Reef); drift diving averages ~1.5 knots","Signature walls: Palancar (accessible), Santa Rosa (expert), Columbia Deep","Parque Nacional Arrecifes de Cozumel reef bracelet = MX$220 (~US$13) per person per day (Jan 2026)","Multiple recompression chambers on-island: SSS/Int''l Hospital + Costamed (DAN preferred provider)","Banco Chinchorro (largest W-hemisphere atoll) is ~30-35 nm off Costa Maya, launched from Xcalak/Mahahual - NOT Cozumel"],"safety":{"emergency":"911","hospital":"Costamed / Cozumel International / Medica San Miguel / General Hospital (town); serious trauma to Cancun private hospitals or US air-evac","recompression_chambers":[{"name":"SSS Recompression Chamber / Medicina Hiperbarica Integral","address":"Calle 5 Sur #21-B, Centro, Cozumel QR 77600","phone":"+52 (987) 872-1430 / 872-2387","emergency_24h":"(987) 103-5524","network":"IDAN Referral Center / UHMS / EUBS"},{"name":"Costamed Hyperbaric Center (Cozumel Medical Center)","opened":"Nov 2013","network":"DAN Recompression Chamber Network Preferred Provider"}],"dan_emergency":"+1-919-684-9111","advisory_level":"L2","malaria":"extremely low / none in tourist zone","dengue":"active - Quintana Roo among highest-activity states 2026; chikungunya/Zika also circulate","water":"bottled/purified only","hurricane":"Jun-Nov (peak Aug-Oct)","dive_no_fly":"12h single / 18h multi-day / 24h deco (DAN); use 24h conservative given repetitive day-boat profiles","drift_diving":"briefing required; SMB; dive within cert; Santa Rosa Wall expert-only","chinchorro":"no chamber at atoll; nearest chambers hours away on mainland/Cozumel - extra-conservative profiles + DAN cover"},"timing":{"peak":"Dec-Mar (calmest seas, clearest skies, 200ft+ viz; Dec24-Jan1 crowded/expensive spike)","shoulder":"Nov (~25-40% off Dec) and May (~20-30% off April); near-peak conditions","green":"May-Sep warmest water ~27-28C / calmest seas; summer humidity + hurricane risk Jun-Nov (peak Aug-Oct)","booking_window_lead_time":"peak dive weeks book well ahead; Chinchorro multi-day + private crewed dive-yacht = book months ahead (limited weather windows / small vessels)","out_of_season_fill_the_beds":"green-summer value story: warmest/calmest water + 20-40% off rooms, thinner crowds, pair with hurricane trip insurance","holiday_event_peaks":["Cozumel Carnival 2026: main parades Feb 14/15/17 (Fat Tue), run Feb 11-18, pre-Carnival Jan 17-Feb 8; floats with pre-Lenten lunar calendar","cruise-ship day-crowds congest San Miguel + nearer reefs — push early boats / south-zone sites"],"campaign_start_trigger":"open peak-season campaign Aug-Sep for Dec-Mar; shoulder push Sep-Oct (Nov) and Feb-Mar (May); Carnival micro-campaign Nov-Dec for mid-Feb"},"jewels":[{"name":"Palancar Reef (Gardens/Caves/Bricks/Horseshoe)","si_tag":"Dive Globally","status":"future","bookable":"2-tank day-boat dive","tier":"essential","commission_path":"dive-op DMC + Viator affiliate","source":"https://www.torntackies.com/cozumel-dive-sites/","hook":"iconic coral pinnacles, archways, swim-throughs, 100-ft+ viz, accessible drift","si":"diveglobal","blurb":"iconic coral pinnacles, archways, swim-throughs, 100-ft+ viz, accessible drift","commission":"dive-op DMC + Viator affiliate"},{"name":"Santa Rosa Wall","si_tag":"Dive Globally","status":"future","bookable":"advanced day-boat dive (expert-only)","tier":"comfort","commission_path":"dive-op DMC","source":"https://www.torntackies.com/cozumel-dive-sites/","timing":"Dec-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"starts ~15 m / 45 ft and drops into the deep; expert-level, with eagle rays, turtles, nurse sharks and giant morays","si":"diveglobal","blurb":"starts ~15 m / 45 ft and drops into the deep; expert-level, with eagle rays, turtles, nurse sharks and giant morays","when":"Dec-Mar","commission":"dive-op DMC"},{"name":"Columbia Deep","si_tag":"Dive Globally","status":"future","bookable":"advanced day-boat dive","tier":"comfort","commission_path":"dive-op DMC","source":"https://cozumelscuba.com/cozumel-dive-sites/","timing":"Dec-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","when":"Dec-Mar","commission":"dive-op DMC"},{"name":"Banco Chinchorro atoll","si_tag":"Dive Liveaboards","status":"future","bookable":"multi-day/liveaboard-style from Xcalak/Mahahual","tier":"premier","commission_path":"Aggressor/liveaboard reseller = Commissioned Agent on application","source":"http://www.pelagiclife.org/chinchorro","timing":"Dec-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","when":"Dec-Mar","commission":"Aggressor/liveaboard reseller = Commissioned Agent on application"},{"name":"Palancar snorkel + El Cielo sandbar","si_tag":"Ocean Adventures","status":"future","bookable":"catamaran/snorkel tour","tier":"essential","commission_path":"Viator/GYG affiliate + DMC","source":"https://cozumelscuba.com/cozumel-dive-sites/","hook":"reef snorkel and shallow turquoise sandbar, no-fly-free family option","si":"ocean","blurb":"reef snorkel and shallow turquoise sandbar, no-fly-free family option","commission":"Viator/GYG affiliate + DMC"}],"faq":[{"q":"Is Cozumel safe to visit right now?","a":"Yes — freely bookable, no hold. Cozumel sits in Quintana Roo, which carries a standard US State Dept Level 2 \"Exercise Increased Caution\" (maintained 2026-05-29) — the same tier the U.S. assigns France, Italy and the UK. Stay in well-lit tourist zones after dark; serious medical cases route to Cancún private hospitals or U.S. air-evac.","source":"travel.state.gov, 2026-07-04","si_tag":"safety"},{"q":"What''s the real risk to plan for in Cozumel?","a":"Decompression discipline, not crime — this is a repetitive multi-day dive island. Follow DAN''s no-fly windows strictly (12h single, 18h multi-day, 24h conservative), because Cozumel''s day-boat profiles stack dives fast; the island has multiple chambers, but a bad no-fly call is the classic mistake. Also plan for dengue (repellent), bottled water and hurricane season (Jun–Nov).","source":"dan.org / travel.state.gov, 2026-07-04","si_tag":"safety"},{"q":"Is drift diving in Cozumel dangerous?","a":"No, when you take the drift briefing seriously — but it is not passive. Expect a near-constant ~1.5-knot current that does the swimming for you; do a controlled descent, stay with the group and dive master, deploy an SMB, and dive within your certification. Santa Rosa Wall is expert-only; Palancar Gardens suits most certified divers.","source":"cozumelscuba.com, 2026-07-04","si_tag":"safety"},{"q":"What are the best dive sites in Cozumel, and can beginners dive them?","a":"Palancar Gardens is the everyone-friendly classic — coral pinnacles, archways and swim-throughs at 100-ft-plus visibility with mild current — while Santa Rosa Wall and Columbia Deep are advanced drifts. Beginners and newly certified divers do best at Palancar; Santa Rosa, dropping from ~15 m into the blue, is expert-only.","source":"torntackies.com, 2026-07-04","si_tag":"diveglobal"},{"q":"Can I do a liveaboard from Cozumel?","a":"Not from Cozumel itself — it is a day-boat island. True liveaboard-style multi-day diving goes to Banco Chinchorro, ~30–35 nm off Costa Maya, launched from Xcalak or Mahahual to the south, not Cozumel. The luxury alternative near Cozumel is a private crewed dive-yacht charter, since overnight liveaboards are effectively banned inside the national park.","source":"pelagiclife.org / islandlifemexico.com, 2026-07-04","si_tag":"liveaboard"},{"q":"Can non-divers snorkel Cozumel, and what''s the reef fee?","a":"Yes — the reef is superb for snorkelers, from Palancar shallows to the El Cielo starfish sandbar by catamaran. Everyone entering the marine park pays the reef bracelet, MX$220 (~US$13) per person per day as of Jan 2026; snorkel tours carry no no-fly restriction, making them a good last-day option before a flight.","source":"cozumelmio.com, 2026-07-04","si_tag":"ocean"},{"q":"Is Cozumel good for a honeymoon or a couples'' dive trip?","a":"Yes — it pairs world-class diving with real staffed villas. Luxury Cozumel and Villa Experience run oceanfront staffed homes (chef, concierge) from ~US$450/night, and there is no branded ultra flag on-island, so for hotel-brand luxury couples ferry to Mayakoba (Rosewood, Banyan Tree) ~an hour away.","source":"luxurycozumel.com, 2026-07-04","si_tag":"romance"},{"q":"When is the best time to dive Cozumel?","a":"December–March is peak, with the calmest seas, clearest skies and legendary 200-ft-plus visibility. November and May are the value sweet spots — near-peak conditions at ~25–40% (Nov) and ~20–30% (May) below Dec rates; May–September brings the warmest, calmest water (~27–28°C) but summer humidity and hurricane risk.","source":"sunsetcozumel.com / mexicotravelandleisure.com, 2026-07-04","si_tag":"planning"}],"seo":{"meta_title":"Cozumel Diving: Drift the Mesoamerican Reef","meta_description":"Cozumel is the Caribbean''s drift-diving crown - Palancar, Santa Rosa Wall and the Mesoamerican Reef, with chambers, no-fly rules and the Chinchorro liveaboard hook.","slug":"cozumel-mexico","primary_keyword":"Cozumel drift diving","long_tail":["Cozumel dive sites Palancar Santa Rosa","Cozumel marine park fee 2026","Banco Chinchorro liveaboard","Cozumel recompression chamber","Mesoamerican Barrier Reef diving"],"search_language":["en","es-MX"],"local_keywords":["buceo en Cozumel","arrecife Palancar Santa Rosa","camara hiperbarica Cozumel","buceo de deriva Cozumel","Parque Nacional Arrecifes de Cozumel","Banco Chinchorro buceo","villa privada de lujo Cozumel"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"diveglobal","status":"future"},{"si":"liveaboard","status":"future","note":"Cozumel = day-boat reef diving; liveaboard/multi-day runs to Banco Chinchorro launch from Xcalak/Mahahual, NOT Cozumel"},{"si":"ocean","status":"future"}],"ultra":[{"name":"Private Paradise Villa","location":"Cozumel (on-island)","what":"oceanfront exclusive-use villa, sleeps up to 24, 40+ staff incl. 7 rotating chefs + British-butler-trained butlers","why_ultra":"full-buyout fully-staffed private-resort — the on-island ultra expression","earning":"villa-agency/DMC commission on application (agent-of-record; no net-rate resale)","virtuoso_value_add":"n/a standalone; attach Virtuoso mainland stay for perks","mor_posture":"clean agent-side; red-flag any villa-inventory mark-up","price_tier":"ultra","source":"https://privateparadisevilla.com/"},{"name":"Private crewed dive-yacht charter","location":"Cozumel / Riviera Maya (on-water)","what":"fully-crewed private yacht (captain+deckhand+dive master, chef/hostess on premium boats), 15+ sites + El Cielo, premium open bar","why_ultra":"ultra dive expression; only luxury ''liveaboard-style'' the park''s vessel-size rules allow (overnight liveaboards effectively banned in-park)","earning":"charter/DMC commission on application","virtuoso_value_add":"n/a direct; pair with Virtuoso stay","mor_posture":"agent-of-record on charter; no net-rate resale","price_tier":"ultra","source":"https://dayyachtcharters.com/cozumel-yacht-charters-luxury-boat-rentals.html"},{"name":"Riviera Maya branded ultra (Rosewood/Banyan Tree Mayakoba, Chable Maroma, Maroma Belmond)","location":"Riviera Maya mainland (ferry + short transfer)","what":"Forbes/branded ultra-luxury resorts + villas; private pools, top spas, PGA course","why_ultra":"nearest true branded ultra flag — no ultra flag on Cozumel itself","earning":"Virtuoso preferred rate + commission (or via host-Virtuoso)","virtuoso_value_add":"upgrade, daily breakfast for two, early check-in/late check-out, ~US$100 credit, VIP welcome (Mayakoba flags)","mor_posture":"standard Virtuoso agent-of-record","price_tier":"ultra","source":"https://www.rosewoodhotels.com/en/mayakoba-riviera-maya"}],"source_verified":"2026-07-04","hero":{"query":"Cozumel, Mexico"},"geo":{"lat":20.423,"lng":-86.9223}}'::jsonb, 30),
